window.TESTS = window.TESTS || [];
TESTS.push({
id: 4, name: "多益 4",
sets: [
{ part: 5, title: "Part 5 單句填空", qs: [
{n:1,q:"The product will be successful; I stake my reputation as an _____ on it.",qz:"這個產品會成功；我以身為分析師的名譽擔保。",o:["analyst","analyze","analysis","analyses"],oz:["分析師","分析（動詞）","分析（名詞）","分析（複數名詞）"],a:0,ex:"as an ___（身為一位…）需要「人」的名詞，且 an 接母音開頭單數 → analyst。"},
{n:2,q:"Bethany found _____ via e-mail that she had been accepted for the position.",qz:"貝瑟妮透過電子郵件得知自己獲得了這個職位。",o:["out","with","about","through"],oz:["發現、得知","與","關於","透過"],a:0,ex:"find out（得知、查明）+ that 子句。"},
{n:3,q:"I get chills of excitement _____ I hear that particular piece of music.",qz:"每當我聽到那首曲子，就興奮得起雞皮疙瘩。",o:["whoever","however","whatever","whenever"],oz:["無論誰","無論如何","無論什麼","每當"],a:3,ex:"表「每當…的時候」→ whenever，後接完整子句。"},
{n:4,q:"I know he made a mistake, but _____ you think you're being a little hard on Bertrand?",qz:"我知道他犯了錯，但你不覺得你對伯特蘭有點太嚴厲了嗎？",o:["not","don't","didn't","haven't"],oz:["不","不（現在式助動詞）","不（過去式）","沒有（完成式）"],a:1,ex:"否定疑問句 Don't you think…?（你不覺得…嗎？），think 是現在式 → don't。"},
{n:5,q:"The popularity of eco-friendly products is _____ of environmental consciousness amongst consumers.",qz:"環保產品的流行顯示出消費者的環保意識。",o:["indicate","indicative","indication","indicates"],oz:["顯示（動詞）","顯示…的（形容詞）","跡象（名詞）","顯示（第三人稱）"],a:1,ex:"be indicative of（顯示出、表明）為固定用法，be 後接形容詞。"},
{n:6,q:"I was horrified to discover that my sweater _____ several sizes after being washed.",qz:"我驚恐地發現毛衣洗過之後縮了好幾號。",o:["shrink","shrank","shrunken","shrinking"],oz:["縮水（原形）","縮水（過去式）","縮水的（過去分詞）","縮水中"],a:1,ex:"that 子句需要動詞，配合 was horrified 的過去時態 → 過去式 shrank。shrunken 是過去分詞，不能單獨當動詞。"},
{n:7,q:"Small businesses have been popping _____ all over the country.",qz:"全國各地紛紛冒出小型企業。",o:["up","on","down","across"],oz:["冒出","繼續","向下","橫越"],a:0,ex:"pop up（突然出現、冒出來）。"},
{n:8,q:"Due to a lack of concrete data, Catalina was only able to offer a series of _____ estimates at the end of her presentation.",qz:"由於缺乏具體資料，卡塔莉娜在簡報最後只能提出一系列粗略的估計。",o:["rocky","rough","rampant","resurgent"],oz:["多岩石的","粗略的","猖獗的","復甦的"],a:1,ex:"rough estimate（粗估）為固定搭配，與「缺乏具體資料」相符。"},
{n:9,q:"The company's New York branch, which has been the most profitable, _____ entirely of experienced personnel.",qz:"公司的紐約分部一直是最賺錢的，它完全由經驗豐富的人員組成。",o:["is composed","composed","composes","is composing"],oz:["由…組成（被動）","組成了","組成（主動）","正在組成"],a:0,ex:"be composed of（由…組成），主詞 branch 為單數 → is composed。"},
{n:10,q:"I just want to say that yesterday, you _____ that troublesome situation admirably. Great job!",qz:"我只是想說，昨天你把那個棘手的狀況處理得非常好。做得好！",o:["handle","handled","have handled","have been handling"],oz:["處理（原形）","處理了（過去式）","已處理","一直在處理"],a:1,ex:"yesterday 是明確的過去時間 → 簡單過去式 handled；現在完成式不能與 yesterday 連用。"},
{n:11,q:"Anya often improvises large portions of the speeches she _____.",qz:"安雅發表演講時常常即興發揮大部分內容。",o:["delivers","offers","hands","passes"],oz:["發表","提供","遞交","傳遞"],a:0,ex:"deliver a speech（發表演說）為固定搭配。"},
{n:12,q:"Inspired by influential entrepreneurs, Mark decided to invest in the tech industry, and he made a _____.",qz:"受到有影響力的企業家啟發，馬克決定投資科技業，結果他賺了一大筆錢。",o:["fortune","richness","opulence","extravagance"],oz:["財富","豐富","富裕","奢侈"],a:0,ex:"make a fortune（發大財）為固定搭配。"},
{n:13,q:"Edmund made a name for _____ by breaking numerous company sales records.",qz:"艾德蒙因打破多項公司銷售紀錄而闖出名號。",o:["his","him","himself","Edmund"],oz:["他的","他（受格）","他自己","艾德蒙"],a:2,ex:"make a name for oneself（成名），主詞與受詞同一人 → 反身代名詞 himself。"},
{n:14,q:"It is a commonly believed myth that the Great Wall of China _____ from space.",qz:"「從太空可以看到中國長城」是一個普遍流傳的迷思。",o:["saw","sees","can see","can be seen"],oz:["看見了","看見","能看見","能被看見"],a:3,ex:"長城是「被看見」的 → 被動 can be seen。"},
{n:15,q:"Feel free to _____ your opinions during the Q & A session after the presentation.",qz:"簡報後的問答時間，歡迎自由發表您的意見。",o:["veto","view","voice","vacate"],oz:["否決","觀看","表達、說出","騰出"],a:2,ex:"voice 當動詞＝表達（voice one's opinions）。"},
{n:16,q:"It took Jesse a long time to get _____ her divorce and be happy again.",qz:"潔西花了很長一段時間才走出離婚的陰霾，重新快樂起來。",o:["into","with","over","under"],oz:["進入","與","克服、走出","在下方"],a:2,ex:"get over（從…中恢復、走出）。"},
{n:17,q:"_____ we subcontract a few of these projects, we will be able to stay on schedule.",qz:"如果我們把其中幾個專案外包出去，就能趕上進度。",o:["If","Whereas","Till","Whether"],oz:["如果","然而","直到","是否"],a:0,ex:"前為條件、後為結果 → If。"},
{n:18,q:"Cynthia tries to frame her _____ in a way that doesn't cause offense.",qz:"辛西亞試著用不冒犯人的方式表達她的批評。",o:["criticize","critic","criticism","critical"],oz:["批評（動詞）","評論家","批評（名詞）","批判的"],a:2,ex:"所有格 her 後接名詞，且是「她所說的批評」→ criticism。critic 是人。"},
{n:19,q:"Though the competition was stiff, I managed _____ the administration position through hard work.",qz:"雖然競爭激烈，我還是靠努力爭取到了行政職位。",o:["securing","to secure","secured","securest"],oz:["取得中","去取得","取得了","最安全的"],a:1,ex:"manage to V（設法做到）→ to secure。"},
{n:20,q:"Considering this is a very important decision, we _____ up our minds yet, so we still need time to think it over.",qz:"考量到這是非常重要的決定，我們還沒下定決心，所以仍需要時間仔細想想。",o:["didn't make","made","haven't made","hadn't been making"],oz:["沒有決定（過去）","決定了","還沒決定（現在完成）","一直沒在決定"],a:2,ex:"yet 搭配現在完成式否定 → haven't made up our minds。"},
{n:21,q:"At this job, you'll need to cope with multiple projects simultaneously, so _____ is a necessary skill if you want to be successful.",qz:"這份工作需要同時處理多項專案，所以如果想成功，一心多用是必備技能。",o:["multitasks","multitasked","multitask","multitasking"],oz:["多工（第三人稱）","多工了","多工（原形）","多工（動名詞）"],a:3,ex:"當句子主詞要用名詞／動名詞 → multitasking。"},
{n:22,q:"We have two dogs and a cat, as we are really _____ animals in our household.",qz:"我們家養了兩隻狗和一隻貓，因為我們家真的很喜歡動物。",o:["keen to","fond of","far from","passed by"],oz:["渴望（接動詞）","喜歡","遠離","經過"],a:1,ex:"be fond of + 名詞（喜歡…）。keen to 後要接動詞原形。"},
{n:23,q:"There is no way of _____ this issue, so you'll just have to face it.",qz:"這個問題無法迴避，所以你只能面對它。",o:["avoiding","annoying","assuming","acknowledging"],oz:["避免","惹惱","假設","承認"],a:0,ex:"後句 you'll just have to face it（只能面對）→ 無法「迴避」→ avoiding。"},
{n:24,q:"Bolstered by his recent impressive performance and good relationship with his superiors, Mitch decided to ask for a _____.",qz:"受到近期亮眼表現與和上司良好關係的鼓舞，米契決定要求升遷。",o:["promotion","prosecution","probation","participation"],oz:["升遷","起訴","試用期／緩刑","參與"],a:0,ex:"表現好又和上司關係好 → 要求升遷 promotion。"},
{n:25,q:"It is important to learn about the traditions and _____ of a place before you visit.",qz:"造訪一個地方之前，先了解當地的傳統和習俗很重要。",o:["customs","customer","customary","customized"],oz:["習俗","顧客","習慣的","客製化的"],a:0,ex:"與 traditions 對等的名詞 → customs（習俗）。"},
{n:26,q:"_____ just talking about starting your own business, you should actually do it.",qz:"與其只是嘴上說要創業，你應該真的去做。",o:["In case of","In spite of","In view of","Instead of"],oz:["萬一","儘管","鑑於","而不是"],a:3,ex:"與其只說不做 → Instead of（而不是）+ V-ing。"},
{n:27,q:"Have we _____ the warehouse about the problem with the recent shipments?",qz:"我們聯絡倉庫談最近出貨的問題了嗎？",o:["contacted","contented","connected","contracted"],oz:["聯絡","使滿足","連接","簽約"],a:0,ex:"contact someone about something（就某事聯絡某人）。"},
{n:28,q:"The film critic described the movie as _____, saying he laughed so hard that he could hardly breathe.",qz:"影評人形容這部電影非常爆笑，說他笑到幾乎無法呼吸。",o:["serious","vicious","hilarious","dangerous"],oz:["嚴肅的","惡毒的","爆笑的","危險的"],a:2,ex:"笑到無法呼吸 → hilarious（極好笑的）。"},
{n:29,q:"As everyone's _____ tonight, let's reconvene tomorrow morning and continue our research.",qz:"既然今晚大家都很累了，我們明天早上再開會繼續研究吧。",o:["exhausts","exhausted","exhausting","exhaustion"],oz:["使筋疲力盡","筋疲力盡的","令人疲憊的","筋疲力盡（名詞）"],a:1,ex:"everyone's ＝ everyone is；人「感到」疲累用 -ed → exhausted。"},
{n:30,q:"_____ I had the money, I don't think I would invest it in that company.",qz:"就算我有錢，我也不認為我會投資那家公司。",o:["Even","Even if","Even when","Even as"],oz:["甚至","即使","即使當…時","正當…時"],a:1,ex:"與現在事實相反的假設（I had… would…）→ Even if（即使）。Even 是副詞，不能連接子句。"}
]},
{ part: 6, title: "Part 6｜人民幣與中國海外投資",
passage: `<p><i>Financial Times</i> contributor Helen Peng asserts that a recent spike of Chinese investment into American real estate is linked to the yuan's potentially looming collapse. If the yuan __(31)__ , many wealthy Chinese investors will lose substantial amounts of capital. Thus, these investors have rushed to fortify their wealth by __(32)__ their assets via international investments.</p><p>__(33)__ Despite these recent efforts on the government's part, many analysts __(34)__ that the flood of international Chinese investments will only ebb temporarily, meaning a more effective long-term solution is needed.</p>`,
pz: `<p>《金融時報》撰稿人 Helen Peng 主張，近來中國對美國房地產的投資激增，與人民幣可能即將崩盤有關。如果人民幣表現疲軟，許多富裕的中國投資人將損失大量資本。因此，這些投資人急於透過海外投資來分散資產，鞏固自己的財富。</p><p>然而，中國政府最近實施了更多資本管制，試圖鼓勵國內投資。儘管政府最近做了這些努力，許多分析師預測，中國海外投資的熱潮只會暫時消退，這表示需要更有效的長期解決方案。</p>`,
qs: [
{n:31,q:"Question 31",o:["floundered","flounders","had floundered","floundering"],oz:["掙扎了","掙扎、表現不佳（現在式）","已經掙扎","掙扎中"],a:1,ex:"條件句 If + 現在式，主句用 will lose → flounders（第三人稱單數）。"},
{n:32,q:"Question 32",o:["divesting","diverging","dispelling","diversifying"],oz:["撤資","分歧","驅散","分散（投資）"],a:3,ex:"透過海外投資「分散」資產以鞏固財富 → diversifying their assets。"},
{n:33,q:"Question 33",o:["These rising commodity prices have led to more than a few countries instituting strict limits on foreign investment.","However, the Chinese government has recently implemented additional capital controls in an attempt to encourage domestic investments.","Fortunately, the predicted prosperity China will enjoy as the currency gains strength will fuel a bright future for the economic giant.","Despite losing everything, many investors say they remain undeterred in their pursuit of building their wealth in the real estate market."],oz:["這些上漲的商品價格導致不少國家嚴格限制外資。","然而，中國政府最近實施了更多資本管制，以鼓勵國內投資。","幸好，隨著人民幣走強，中國將迎來繁榮。","儘管失去一切，許多投資人仍不放棄在房市累積財富。"],a:1,ex:"下一句說「Despite these recent efforts on the government's part」→ 前句必須提到政府的作為 → (B)。"},
{n:34,q:"Question 34",o:["predict","prediction","predictable","predictably"],oz:["預測（動詞）","預測（名詞）","可預測的","可預料地"],a:0,ex:"主詞 many analysts 後需要動詞，後接 that 子句 → predict。"}
]},
{ part: 6, title: "Part 6｜運動提升工作效率",
passage: `<p>Although it may seem counterproductive, an hour of exercise a day may allow you to __(35)__ more than if you had simply sat for that hour and continued trying to get work done. __(36)__</p><p>For one, exercise reduces stress and causes your brain to release endorphins and dopamine. Additionally, working __(37)__ has been proven to increase creativity, focus, and memory capacity. So the next time you're feeling uninspired or __(38)__ down, take some time (an hour or so) to run, do some push-ups, or tone that stomach.</p>`,
pz: `<p>雖然看似適得其反，但每天運動一小時，可能比你單純坐著那一小時繼續努力工作，完成更多事情。許多醫學與心理學研究指出，運動對心智能力的好處既有益又多元。</p><p>首先，運動能減輕壓力，並讓大腦釋放腦內啡和多巴胺。此外，運動已被證實能提升創造力、專注力和記憶力。所以下次你覺得缺乏靈感或身心俱疲時，花點時間（一小時左右）去跑步、做幾下伏地挺身，或練練腹肌吧。</p>`,
qs: [
{n:35,q:"Question 35",o:["assess","oversee","sustain","accomplish"],oz:["評估","監督","維持","完成"],a:3,ex:"與 get work done 對照 → 運動反而讓你「完成」更多 → accomplish。"},
{n:36,q:"Question 36",o:["If you have a large amount of work to do, portioning it off into smaller groups of tasks may help you get it done sooner and better.","According to many medical and psychological studies, the effects of exercise on one's mental capacity are beneficial and numerous.","Flexing your wrists, hands, and fingers is key to preventing repetitive stress injuries.","One strategy is to alternate between a standing and squatting position at your desk until your muscles warm up."],oz:["工作量大時，拆成小任務可以更快更好地完成。","許多醫學與心理學研究指出，運動對心智能力的好處既有益又多元。","活動手腕和手指是預防重複性勞損的關鍵。","一個策略是在座位上交替站立和蹲下直到肌肉熱身。"],a:1,ex:"下一段 For one… Additionally… 列舉運動對大腦的好處 → 前面要有「運動對心智有許多好處」的主題句。"},
{n:37,q:"Question 37",o:["out","with","down","smart"],oz:["運動、健身（work out）","與","向下","聰明地"],a:0,ex:"work out（運動健身），working out 當主詞。"},
{n:38,q:"Question 38",o:["grinding","grinds","grind","ground"],oz:["磨（進行式）","磨（第三人稱）","磨（原形）","被磨損的（過去分詞）"],a:3,ex:"與 uninspired（形容詞）對等，需過去分詞當形容詞：ground down（被磨得筋疲力盡）。grind 的過去分詞是 ground。"}
]},
{ part: 6, title: "Part 6｜徵求波斯語口譯",
passage: `<p>Wanted: Native Farsi speaker for interpreting role with Iranian trade firm</p><p>Requirements:</p><p>• __(39)__ in Farsi and English a must<br>• A degree in mass communications, media, or a similar field is __(40)__<br>• Excellent interpersonal skills<br>• An ability to interpret __(41)__ , conveying the main points clearly and concisely</p><p>__(42)__</p>`,
pz: `<p>徵才：伊朗貿易公司徵求母語為波斯語的口譯人員</p><p>條件：</p><p>• 必須能流利使用波斯語和英語<br>• 具大眾傳播、媒體或相關領域學位者優先<br>• 優秀的人際溝通能力<br>• 能即時口譯，清楚簡潔地傳達重點</p><p>如果你認為自己符合以上條件，請與我們聯繫。</p>`,
qs: [
{n:39,q:"Question 39",o:["Flow","Fluidity","Fluency","Fluctuation"],oz:["流動","流動性","（語言）流利","波動"],a:2,ex:"語言能力用 fluency（流利度）。"},
{n:40,q:"Question 40",o:["preferring","prefers","preferable","preference"],oz:["偏好中","偏好（動詞）","較佳的、優先的","偏好（名詞）"],a:2,ex:"is 後接形容詞 → preferable（為佳、優先）。徵才廣告常見用法。"},
{n:41,q:"Question 41",o:["at all times","in good time","ahead of time","in real time"],oz:["隨時","及時、早早地","提前","即時"],a:3,ex:"口譯是「即時」翻譯 → in real time。"},
{n:42,q:"Question 42",o:["If you have any information, please e-mail us at rainian@plezdeck.com.","Some restrictions may apply, so please inquire at the store for details.","Please enclose payment in full if you have not already remitted it to us.","If you believe you fulfill these criteria, please get in touch with us."],oz:["如果你有任何資訊，請寄信到 rainian@plezdeck.com。","可能有些限制，詳情請洽門市。","若尚未付款，請附上全額款項。","如果你認為自己符合以上條件，請與我們聯繫。"],a:3,ex:"徵才廣告列完條件後，結尾請符合條件者聯絡 → (D)。"}
]},
{ part: 6, title: "Part 6｜Invoice for Freelancers 自由工作者發票",
passage: `<p><b>Invoice for Freelancers</b></p><p><b>Name</b>: Timothy Brown</p><p><b>Project</b>: Voice-over for Hannigan's Honey Commercial</p><p><b>Description of project</b>: The artist will perform a two-minute commercial __(43)__ the client's script. The script is roughly 300 words, __(44)__ a short song.</p><p><b>Payment</b>: $500 upon __(45)__ of the entire project</p><p><b>Signature of artist</b>: _____</p><p><b>Signature of Studio Manager</b>: <i>Helen Delano</i></p><p><b>Notes</b>: Fixes to the original recording are mandatory and are to be performed at a later date. __(46)__</p>`,
pz: `<p><b>自由工作者發票</b></p><p><b>姓名</b>：Timothy Brown</p><p><b>專案</b>：Hannigan's 蜂蜜廣告配音</p><p><b>專案說明</b>：配音員將根據客戶的腳本演出一支兩分鐘的廣告。腳本約 300 字，包括一首短歌。</p><p><b>付款</b>：整個專案完成後支付 500 美元</p><p><b>配音員簽名</b>：_____</p><p><b>錄音室經理簽名</b>：Helen Delano</p><p><b>備註</b>：原始錄音的修正為必要項目，將於日後進行。所有修正均不另外付費。</p>`,
qs: [
{n:43,q:"Question 43",o:["put on","given to","based on","made from"],oz:["穿上／上演","給予","根據","由…製成"],a:2,ex:"根據客戶的腳本演出 → based on。"},
{n:44,q:"Question 44",o:["included","inclusion","including","to include"],oz:["被包含的","包含（名詞）","包括","去包含"],a:2,ex:"including + 名詞（包括…）當介系詞使用。"},
{n:45,q:"Question 45",o:["discretion","deduction","transaction","completion"],oz:["斟酌","扣除","交易","完成"],a:3,ex:"upon completion of the project（專案完成後）付款。"},
{n:46,q:"Question 46",o:["Fixes will be made on the day of recording.","Fixes will not require additional performance.","All fixes do not warrant additional payment.","The freelancer may choose to forgo any and all revisions."],oz:["修正會在錄音當天進行。","修正不需要額外演出。","所有修正均不另外付費。","自由工作者可選擇放棄所有修改。"],a:2,ex:"前句說修正是必要的、日後進行 → 補充「修正不另外付費」。(A) 與 at a later date 矛盾；(D) 與 mandatory 矛盾。"}
]},
{ part: 7, title: "Part 7｜ATN-67 產品召回",
passage: `<p style="text-align:center"><b>RECALL ANNOUNCEMENT</b></p><p><i>As of July 5, Citidine Industries will no longer be selling model ATN-67. If you have purchased this product, please contact us for a refund and replacement.</i></p><p><b>Comments:</b></p><p><b>Judy K.:</b> I need the ATN-67 for my company's product. I have very specific specifications. Will the replacement be the exact same size?<br>　<i>Citidine: Due to the issue with this model, the replacement will be slightly larger.</i></p><p><b>Robert M.:</b> My company purchased 100 of this model seven years ago, and some have passed their warranty. Will I still be able to get replacements?<br>　<i>Citidine: Yes, as long as it is model ATN-67, you can get a replacement.</i></p><p><b>Jesse V.:</b> Let me make sure I get it. Even if our products using this model are working correctly, we should still get them replaced?<br>　<i>Citidine: Yes, because it is a safety issue.</i></p>`,
pz: `<p style="text-align:center"><b>召回公告</b></p><p><i>自 7 月 5 日起，Citidine 工業將不再販售 ATN-67 型號。若您購買過此產品，請與我們聯繫以辦理退款與更換。</i></p><p><b>留言：</b></p><p><b>Judy K.：</b>我公司的產品需要用到 ATN-67，規格要求非常精確。替換品的尺寸會完全一樣嗎？<br>　<i>Citidine：由於此型號的問題，替換品會稍微大一點。</i></p><p><b>Robert M.：</b>我公司七年前買了 100 個這個型號，有些已經過了保固期。我還能更換嗎？<br>　<i>Citidine：可以，只要是 ATN-67 型號都能更換。</i></p><p><b>Jesse V.：</b>讓我確認一下我理解得對不對。即使我們用這個型號的產品運作正常，還是應該更換嗎？<br>　<i>Citidine：是的，因為這是安全問題。</i></p>`,
qs: [
{n:47,q:"What is the reason for the recall?",qz:"召回的原因是什麼？",o:["It is too expensive.","It is dangerous.","They are out of stock.","They want to upgrade the products."],oz:["太貴了。","它有危險。","缺貨。","想升級產品。"],a:1,ex:"Citidine 回覆「because it is a safety issue」→ 有安全疑慮。"},
{n:48,q:"What does Jesse V. mean when he writes, \"Let me make sure I get it\"?",qz:"Jesse V. 寫「Let me make sure I get it」是什麼意思？",o:["He wants to receive the replacement as soon as possible.","He wants to clarify something about the announcement.","He wants to be sure the company refunds the model.","He wants to order a new product from the company."],oz:["他想盡快拿到替換品。","他想釐清公告中的某件事。","他想確定公司會退款。","他想向公司訂購新產品。"],a:1,ex:"get it ＝ 理解。他接著問「運作正常也要換嗎？」→ 想釐清公告內容。"}
]},
{ part: 7, title: "Part 7｜出差費用報銷單",
passage: `<p>Employee ID: 5543267　　Name: Edgar Newbower</p><table><tr><th></th><th>Date of Expense(s)</th><th>Purpose: Summarize the nature of the deductible expense.</th></tr><tr><td>1</td><td>Jan. 1</td><td>Luncheon with Alameda Corp. representatives</td></tr><tr><td>2</td><td>Apr. 9</td><td>Taxi across town to shuttle Valence Corp. staff from the airport</td></tr><tr><td>3</td><td>May 10-15</td><td>Trip to Napa Valley, USA, for tech conference</td></tr><tr><td>4</td><td>Nov. 2-9</td><td>Trip to Prague, Czech Republic, for tech conference</td></tr></table><p>Summary of Expenses - Cross-reference the business purpose to each item on the statement by writing the business purpose # next to the itemized lines</p><table><tr><th></th><th>Date of Expense(s)</th><th>Airfare</th><th>Ground Trans</th><th>Accommodations</th><th>Meals</th><th>Total</th></tr><tr><td>1</td><td>Jan. 1</td><td>X</td><td>X</td><td>X</td><td>US$300</td><td>US$300</td></tr><tr><td>2</td><td>Apr. 9</td><td>X</td><td>US$100</td><td>X</td><td>X</td><td>US$100</td></tr><tr><td>3</td><td>May 10-15</td><td>US$650</td><td>US$250</td><td>US$900</td><td>US$500</td><td>US$2,300</td></tr><tr><td>4</td><td>Nov. 2-9</td><td>US$1,200</td><td>US$100</td><td>US$700</td><td>US$200</td><td>US$2,200</td></tr><tr><td></td><td>Total</td><td>US$1,850</td><td>US$450</td><td>US$1,600</td><td>US$1,000</td><td>US$4,900</td></tr></table><p><b>Prepared by:</b> Edgar Newbower<br><b>Approved by:</b> Cynthia Galbatta</p>`,
pz: `<p>員工編號：5543267　姓名：Edgar Newbower</p><p><b>費用日期與目的</b><br>1. 1 月 1 日：與 Alameda 公司代表共進午餐<br>2. 4 月 9 日：搭計程車穿越市區，從機場接送 Valence 公司員工<br>3. 5 月 10–15 日：前往美國納帕谷參加科技研討會<br>4. 11 月 2–9 日：前往捷克布拉格參加科技研討會</p><p><b>費用摘要</b>（機票／地面交通／住宿／餐費／合計）<br>1. 1/1：—／—／—／$300／$300<br>2. 4/9：—／$100／—／—／$100<br>3. 5/10–15：$650／$250／$900／$500／$2,300<br>4. 11/2–9：$1,200／$100／$700／$200／$2,200<br>總計：$1,850／$450／$1,600／$1,000／$4,900</p><p>製表：Edgar Newbower　核准：Cynthia Galbatta</p>`,
qs: [
{n:49,q:"What do we know about Edgar Newbower?",qz:"關於 Edgar Newbower 我們知道什麼？",o:["He doesn't use taxis while on business trips.","He is Cynthia Galbatta's immediate superior.","He doesn't travel internationally for business.","He works in either the tech industry or a related field."],oz:["他出差時不搭計程車。","他是 Cynthia Galbatta 的直屬上司。","他不出國出差。","他從事科技業或相關領域。"],a:3,ex:"兩次出差都是參加 tech conference（科技研討會）→ 科技相關產業。他有搭計程車、也去過布拉格；Cynthia 核准他的報銷，比較像是上司。"},
{n:50,q:"Based on his reimbursement claims above, how could Edgar Newbower's company most effectively cut costs in the future?",qz:"根據上面的報銷，Edgar Newbower 的公司要怎麼最有效地降低未來成本？",o:["Only send him to local conferences","Restrict him to only the cheapest hotels","Stop sending him on corporate luncheons","Have him use his own vehicle to meet clients at the airport"],oz:["只派他參加國內研討會","限制他只住最便宜的旅館","不再派他參加公司午餐會","讓他自己開車去機場接客戶"],a:0,ex:"最大的開銷是兩趟研討會出差（$2,300、$2,200），尤其是機票 → 只參加當地研討會最省。"}
]},
{ part: 7, title: "Part 7｜Dandelion 戲劇工作坊",
passage: `<p><b>Dandelion Theater Workshop — Learning From the Masters</b></p><p>This two-day drama workshop will introduce budding stage performers to the theories of two masters of theater who held contrasting approaches.</p><p><b><i>Day 1</i></b><br>Building a Role: The Stanislavskian Approach</p><p>Stanislavski, the great Russian director, is known as the father of method acting. His approach to performance involves getting so far under the skin of a character that you almost become the person you are portraying. Even today, Hollywood stars such as Robert De Niro, Dustin Hoffman, and Meryl Streep use these methods to build a character. Discover the techniques behind this approach.</p><p><b><i>Day 2</i></b><br>Suspending Belief: Brecht's Alienation Effect</p><p>Famed for writing important works such as <i>Mother Courage</i> and <i>The Threepenny Opera</i>, Brecht introduced a style that challenged traditional notions of theater. The German playwright believed that theater and movies were guilty of using cheap tricks to get people to perceive their plots and characters as indicative of reality. He wanted to end this, partly by making it clear that the stage performer is simply playing a role within an artistic construct.</p>`,
pz: `<p><b>Dandelion 劇場工作坊——向大師學習</b></p><p>這個為期兩天的戲劇工作坊，將向新進舞台表演者介紹兩位觀點對立的戲劇大師的理論。</p><p><b>第一天</b><br>塑造角色：史坦尼斯拉夫斯基的方法</p><p>俄國偉大導演史坦尼斯拉夫斯基被稱為「方法演技之父」。他的表演方法是深入角色內心，深到你幾乎變成你所扮演的那個人。直到今天，勞勃・狄尼洛、達斯汀・霍夫曼和梅莉・史翠普等好萊塢巨星仍用這些方法塑造角色。來探索這個方法背後的技巧吧。</p><p><b>第二天</b><br>暫停信以為真：布萊希特的疏離效果</p><p>以《勇氣媽媽》和《三便士歌劇》等重要作品聞名的布萊希特，提出了一種挑戰傳統戲劇觀念的風格。這位德國劇作家認為，戲劇和電影用廉價的手法讓觀眾把劇情和角色當成現實。他想終結這種做法，部分方式就是清楚表明舞台表演者只是在一個藝術建構中扮演角色。</p>`,
qs: [
{n:51,q:"What kind of activity might this workshop most likely involve?",qz:"這個工作坊最可能包含哪種活動？",o:["Acting","Writing","Filming","Painting"],oz:["表演","寫作","拍攝","繪畫"],a:0,ex:"對象是 stage performers（舞台表演者），內容是塑造角色、方法演技 → 表演。"},
{n:52,q:"Who is known as the father of method acting?",qz:"誰被稱為方法演技之父？",o:["Stanislavski","Brecht","Dustin Hoffman","Robert De Niro"],oz:["史坦尼斯拉夫斯基","布萊希特","達斯汀・霍夫曼","勞勃・狄尼洛"],a:0,ex:"「Stanislavski… is known as the father of method acting」。"}
]},
{ part: 7, title: "Part 7｜老鼠會 Pyramid Scheme",
passage: `<p>A pyramid scheme is a term applied to a business which derives most of its money from recruitment rather than selling products. The scheme works as follows: A representative of the pyramid scheme entices a new client to join the company's ranks by promising them vast amounts of wealth and opportunity. Often, they claim that the prospective client must buy into the company (usually by purchasing products) and can then earn a profit by reselling the products. The representative may also strongly suggest that the prospective client and/or new staff member encourage five or more people—often the new member's friends and family—to buy in as well. Doing this will allow the new member to recoup their enlistment fee. However, this model isn't sustainable, because if it were repeated 13 times, the amount of recruits would be larger than the entire population on Earth. Presently, most multilevel marketing companies have been accused of being pyramid schemes. About 99 percent of people who enter multilevel marketing companies fail to earn money, and many of them actually lose far more money than they initially invest.</p>`,
pz: `<p>「老鼠會（金字塔騙局）」指的是主要靠招募新成員、而非銷售產品賺錢的生意。運作方式如下：老鼠會的代表以承諾大量財富和機會，引誘新客戶加入公司行列。他們常聲稱潛在客戶必須先入股（通常是購買產品），然後就能靠轉售產品獲利。代表也可能強烈建議潛在客戶或新成員，再鼓勵五個或更多人——通常是新成員的親友——也加入。這樣做能讓新成員收回入會費。然而，這種模式無法持續，因為如果重複 13 次，招募人數就會超過地球總人口。目前大多數多層次傳銷公司都被指控是老鼠會。約 99% 加入多層次傳銷公司的人都沒賺到錢，其中許多人實際上賠掉的錢遠超過最初的投入。</p>`,
qs: [
{n:53,q:"According to the passage, how does a pyramid scheme acquire most of its profits?",qz:"根據文章，老鼠會大部分的利潤從哪裡來？",o:["By licensing rights","By selling products","By suing slanderers","By recruiting members"],oz:["授權","銷售產品","控告誹謗者","招募成員"],a:3,ex:"「derives most of its money from recruitment rather than selling products」→ 靠招募。"},
{n:54,q:"Why is it impossible for every member of a pyramid scheme to make their money back by enlisting new members?",qz:"為什麼老鼠會的每個成員不可能都靠招募新人回本？",o:["Most pyramid scheme members are notoriously antisocial.","The company doesn't allow employees to enlist new employees.","The police will definitely jail anyone involved in a pyramid scheme.","There aren't enough people on Earth for this to be done many times."],oz:["大多數成員出了名的孤僻。","公司不允許員工招募新員工。","警察一定會抓所有參與者。","地球上沒有足夠的人能讓這重複很多次。"],a:3,ex:"「if it were repeated 13 times, the amount of recruits would be larger than the entire population on Earth」。"}
]},
{ part: 7, title: "Part 7｜卡內基《人性的弱點》",
passage: `<p>First published in 1936, <i>How to Win Friends and Influence People</i> is considered to be one of the most successful self-help books of all time. —[1]— The book was published after Leon Shimkin, the eventual chairman of the publishing company Simon &amp; Schuster, convinced Dale Carnegie to let a stenographer take notes on Carnegie's self-improvement courses and revise them for publication—though Carnegie is still credited as the author. —[2]— Apart from its amusing stories and everyday wisdom, the book gives detailed instructions on how best to interact with people, claiming that it will improve your business life, enrich your home life, and make you an effective leader. Although content varies between editions, the book is divided into seven major sections that cover business skills, proper correspondence, and social interactions with strangers, friends, and family. —[3]— Carnegie asserts that whether negotiating, forming business connections, or simply mingling, it is best to express a genuine interest in the person with whom you are conversing and to let them do most of the talking. By being a good listener, Carnegie argues, you'll be capable of discerning what the other person likes. You can then steer the conversation toward an area of that person's interest. —[4]—</p>`,
pz: `<p>《人性的弱點（How to Win Friends and Influence People）》於 1936 年首次出版，被視為史上最成功的自我成長書之一。—[1]— 這本書的出版，是因為後來成為 Simon &amp; Schuster 出版社董事長的 Leon Shimkin，說服戴爾・卡內基讓一位速記員為他的自我成長課程做筆記並修訂出版——不過作者仍掛名卡內基。—[2]— 除了有趣的故事和日常智慧外，這本書詳細說明了如何與人互動，宣稱能改善你的職場生活、豐富你的家庭生活，並讓你成為有效的領導者。雖然各版本內容有所不同，但全書分為七大部分，涵蓋商業技巧、得體的書信往來，以及與陌生人、朋友和家人的社交互動。—[3]— 卡內基主張，無論是談判、建立商業人脈，或只是交際應酬，最好的方式都是對交談對象表現出真誠的興趣，並讓對方多說話。卡內基認為，做個好的傾聽者，你就能察覺對方喜歡什麼，然後把話題引導到對方感興趣的領域。—[4]— 談論對方覺得有趣的事，對方也會連帶覺得你很有趣。</p>`,
qs: [
{n:55,q:"Who was Dale Carnegie?",qz:"戴爾・卡內基是誰？",o:["The chairman of Simon & Schuster","The best stenographer at his company","The immediate superior of Leon Shimkin","The author of a best-selling self-help book"],oz:["Simon & Schuster 的董事長","他公司裡最好的速記員","Leon Shimkin 的直屬上司","暢銷自我成長書的作者"],a:3,ex:"「Carnegie is still credited as the author」，而這本書是最成功的自我成長書之一。董事長是 Shimkin。"},
{n:56,q:"What is something Carnegie asserts is crucial to better social relations?",qz:"卡內基認為改善人際關係的關鍵是什麼？",o:["Conversing loudly","Listening attentively","Dressing eccentrically","Speaking domineeringly"],oz:["大聲交談","專心傾聽","穿著古怪","說話強勢"],a:1,ex:"「let them do most of the talking. By being a good listener…」→ 專心傾聽。"},
{n:57,q:"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"By talking about something the other person finds interesting, the other person will find you interesting by extension.\"",qz:"下列句子最適合放在哪個位置？\n「談論對方覺得有趣的事，對方也會連帶覺得你很有趣。」",o:["[1]","[2]","[3]","[4]"],oz:["[1]","[2]","[3]","[4]"],a:3,ex:"[4] 前一句說「把話題引導到對方感興趣的領域」，接著說明這樣做的效果最自然。"}
]},
{ part: 7, title: "Part 7｜HostBoard 網域續約",
passage: `<p>To: tjarecki@beatmail.com<br>From: assist@hostboard.com<br>Sent: Tues, 03/09, 08:00 a.m.</p><p>Hello Tim Jarecki:</p><p>This is a reminder that your HostBoard services are due for renewal on 2017/07/30, 05:00:00.</p><p>Your service(s) will auto-renew seven days prior to the renewal date using the credit card details currently saved in the payment details section of your account. This is to ensure there is no interruption of service.</p><p>Here is a list of your service(s) due to renew:</p><p>• REGISTER: .com Domain Registration, themasterartblogger.com, $11.49<br>• REGISTER: .com Domain Registration, contemporaryartsyman.com, $13.49<br>　Subtotal: $24.98<br>　Tax (0%): $0.00<br>　Total: $24.98</p><p>Please take a moment to ensure that your payment details are up to date by logging into your control panel at https://chl.hostboard.com.</p><p>If you should require any further assistance, please get in touch with the billing team at https://chl.hostboard.com/support. Alternatively, you can call us at 1-866-631-7220, and we will be happy to provide any help you may need. Thank you for choosing HostBoard as your Web site hosting service.</p><p>Warm regards,<br>Your HostBoard Team</p>`,
pz: `<p>收件者：tjarecki@beatmail.com<br>寄件者：assist@hostboard.com<br>寄件時間：3/9（週二）上午 8:00</p><p>Tim Jarecki 您好：</p><p>提醒您，您的 HostBoard 服務將於 2017/07/30 05:00:00 到期續約。</p><p>您的服務將在續約日前七天，使用您帳戶付款資料中儲存的信用卡自動續約，以確保服務不中斷。</p><p>以下是即將續約的服務：</p><p>• 註冊：.com 網域註冊，themasterartblogger.com，$11.49<br>• 註冊：.com 網域註冊，contemporaryartsyman.com，$13.49<br>　小計 $24.98；稅（0%）$0.00；總計 $24.98</p><p>請花點時間登入控制台 https://chl.hostboard.com，確認您的付款資料是最新的。</p><p>如需進一步協助，請透過 https://chl.hostboard.com/support 聯絡帳務團隊。您也可以撥打 1-866-631-7220，我們很樂意提供您所需的任何協助。感謝您選擇 HostBoard 作為您的網站代管服務。</p><p>HostBoard 團隊敬上</p>`,
qs: [
{n:58,q:"What service is NOT provided by HostBoard?",qz:"下列哪一項服務 HostBoard「沒有」提供？",o:["Automated payment","Customer support","Web site domain registration","Domain monetization"],oz:["自動付款","客戶支援","網站網域註冊","網域變現"],a:3,ex:"文中有自動續約付款、客服電話、網域註冊，沒有提到網域變現。"},
{n:59,q:"What will happen a week before July 30?",qz:"7 月 30 日前一週會發生什麼事？",o:["Assistance will be provided by service personnel.","Payment information will be automatically updated.","HostBoard's control panel will contact the billing team.","Registration of Tim Jarecki's Web sites will be renewed."],oz:["服務人員會提供協助。","付款資料會自動更新。","控制台會聯絡帳務團隊。","Tim Jarecki 的網站註冊會被續約。"],a:3,ex:"「will auto-renew seven days prior to the renewal date」→ 前一週自動續約網域。付款資料要他自己更新。"},
{n:60,q:"Who can be contacted at the phone number provided?",qz:"撥打所提供的電話號碼可以聯絡到誰？",o:["Tim Jarecki","Financial consultants","Customer service staff","HostBoard's management"],oz:["Tim Jarecki","理財顧問","客服人員","HostBoard 管理階層"],a:2,ex:"「call us at 1-866-631-7220, and we will be happy to provide any help」→ 客服人員。"}
]},
{ part: 7, title: "Part 7｜垃圾清運網站更新",
passage: `<p><b>Flora [10:30 a.m.]</b><br>Where are we with the Web site update? It needs to be ready to go by the end of the week.</p><p><b>Hamid [10:31 a.m.]</b><br>Had a bit of a wrench in the plans. The city changed collection guidelines AGAIN, so we had to rewrite a few of the pickup instructions. Should still be good to go by the deadline.</p><p><b>Flora [10:34 a.m.]</b><br>Unless the city decides to make another change. They need to learn how to make a plan and stick to it. How about winter collection? Did anything change there?</p><p><b>Guzman [10:36 a.m.]</b><br>Yes, actually. They decided some routes won't have guaranteed collection during the winter anymore. That's only for recycling, though.</p><p><b>Flora [10:38 a.m.]</b><br>OK, thanks for letting me know. Can you run through the new pickup instruction changes for me really quick?</p><p><b>Hamid [10:40 a.m.]</b><br>Sure. Carts and bins must be at collection point by 7:00 a.m. on pickup days—changed from 6:30 a.m. Carts must be one meter away from other objects—changed from 1.5 meters. Guzman, did I miss anything?</p><p><b>Guzman [10:42 a.m.]</b><br>Nope. That all looks right to me. Oh, and Flora—your suggestion for the design was great. Web site is going to look clean and modern. There should also be fewer clicks required now to navigate through pages.</p><p><b>Flora [10:43 a.m.]</b><br>I'm happy to hear it. Can't wait to see the finished product! Oh, who will we be sending out for pickup tomorrow morning? The new guys?</p><p><b>Hamid [10:44 a.m.]</b><br>Yep. Going to let the newbies drive the truck. Hopefully they don't burn down the whole city!</p>`,
pz: `<p><b>Flora［上午 10:30］</b><br>網站更新進行得如何？週末前要準備好上線。</p><p><b>Hamid［10:31］</b><br>計畫出了點狀況。市政府「又」改了清運規定，所以我們得重寫幾條收運說明。應該還是能在期限前完成。</p><p><b>Flora［10:34］</b><br>除非市政府又決定改。他們得學會訂好計畫然後照著做。冬季清運呢？那部分有改嗎？</p><p><b>Guzman［10:36］</b><br>其實有。他們決定有些路線冬天不再保證收運了。不過只限資源回收。</p><p><b>Flora［10:38］</b><br>好，謝謝告知。可以幫我快速講一下新的收運說明改了哪些嗎？</p><p><b>Hamid［10:40］</b><br>當然。收運日當天，推車和垃圾桶必須在早上 7:00 前放到收運點——原本是 6:30。推車必須與其他物品相距一公尺——原本是 1.5 公尺。Guzman，我有漏掉什麼嗎？</p><p><b>Guzman［10:42］</b><br>沒有，看起來都對。喔還有 Flora——你的設計建議很棒。網站會看起來乾淨又現代。現在瀏覽頁面需要點擊的次數也應該更少。</p><p><b>Flora［10:43］</b><br>很高興聽到。等不及看成品了！喔，明天早上要派誰去收運？新來的那幾個嗎？</p><p><b>Hamid［10:44］</b><br>對。要讓菜鳥們開垃圾車。希望他們別把整座城市燒掉！</p>`,
qs: [
{n:61,q:"In which field are the speakers employed?",qz:"對話者在哪個領域工作？",o:["Web design","City planning","Waste management","Information technology"],oz:["網頁設計","都市計畫","廢棄物管理（垃圾清運）","資訊科技"],a:2,ex:"他們派人開車去收運垃圾（pickup、drive the truck）→ 垃圾清運業。網站只是他們公司的網站。"},
{n:62,q:"What is NOT a change put forth by the city?",qz:"下列何者「不是」市政府提出的變更？",o:["Garbage collection days","Bin collection time","Recycling collection routes","Cart collection time"],oz:["垃圾收運日","垃圾桶收運時間","資源回收路線","推車收運時間"],a:0,ex:"改的是時間（6:30→7:00）、距離、冬季回收路線；收運「日」沒有改。"},
{n:63,q:"What does Hamid imply when he writes, \"Hopefully they don't burn down the whole city\"?",qz:"Hamid 寫「希望他們別把整座城市燒掉」暗示什麼？",o:["The fire department will be needed.","There is an issue with fire prevention.","The new employees might get themselves hurt.","The new employees have little to no experience."],oz:["會需要消防隊。","防火有問題。","新員工可能會受傷。","新員工幾乎沒有經驗。"],a:3,ex:"開玩笑的誇飾，意思是菜鳥（newbies）沒經驗，擔心他們搞砸。"},
{n:64,q:"Where must carts be located under the new guidelines?",qz:"根據新規定，推車必須放在哪裡？",o:["1.5 meters from other objects","One meter from other objects","2.5 meters from other objects","Two meters from other objects"],oz:["距其他物品 1.5 公尺","距其他物品 1 公尺","距其他物品 2.5 公尺","距其他物品 2 公尺"],a:1,ex:"「one meter away from other objects—changed from 1.5 meters」→ 新規定 1 公尺。1.5 是舊規定，陷阱！"}
]},
{ part: 7, title: "Part 7｜牙膏供應商的信",
passage: `<p>To: f.zappa@dentium.net<br>From: harrietherrman@freshbreath.org</p><p>Dear Frank:</p><p>Further to our previous correspondence, I understand your situation concerning the factory fire, but unless you can move quickly to rectify the situation, I may have to take my company's business elsewhere. We need the toothpaste as soon as possible. Perhaps you could use stock from one of your other factories in the south of the country? Let me know ASAP whether that might be possible.</p><p>On a separate note: For many years now, we have been purchasing a range of products from you, including mouthwash, brushes, and dental floss. I regret to inform you that we wish to discontinue purchasing the latter product from you as we have found a cheaper supplier in Montana. We thought it was only fair to give you advanced warning of this, and we will continue to purchase from you until the end of the next quarter.</p><p>Regards,<br>Harriett</p>`,
pz: `<p>收件者：f.zappa@dentium.net<br>寄件者：harrietherrman@freshbreath.org</p><p>親愛的 Frank：</p><p>延續我們先前的通信，我了解你們工廠火災的狀況，但除非你能迅速補救，否則我可能得把公司的生意轉給別家。我們需要盡快拿到牙膏。也許你可以從南部其他工廠調貨？請盡快告訴我是否可行。</p><p>另外一件事：多年來我們一直向你們購買一系列產品，包括漱口水、牙刷和牙線。很遺憾通知你，我們打算停止向你們購買後者（牙線），因為我們在蒙大拿州找到了更便宜的供應商。我們認為提前告知你才公平，我們會繼續向你們購買到下一季結束。</p><p>Harriett 敬上</p>`,
qs: [
{n:65,q:"What is known about Frank's company?",qz:"關於 Frank 的公司我們知道什麼？",o:["They supply dental products.","They make fire safety products.","They are moving the location of their factory.","They purchase items from Harriet's company."],oz:["他們供應牙科產品。","他們製造防火產品。","他們要搬遷工廠。","他們向 Harriet 的公司買東西。"],a:0,ex:"Harriett 向他們購買牙膏、漱口水、牙刷、牙線 → 供應牙科產品。方向是 Harriett 向 Frank 買，(D) 相反。"},
{n:66,q:"What can be inferred to have happened?",qz:"可以推論發生了什麼事？",o:["Frank's company needs an advance on a loan.","Frank's company has experienced an accident.","Frank's company has lost stock in the south of the country.","Frank's company is now purchasing from a different supplier."],oz:["Frank 的公司需要預支貸款。","Frank 的公司發生了意外。","Frank 的公司在南部的庫存沒了。","Frank 的公司正在向別的供應商進貨。"],a:1,ex:"「your situation concerning the factory fire」→ 工廠發生火災（意外）。南部工廠是建議調貨的地方。"},
{n:67,q:"What is going to happen at the end of the next quarter?",qz:"下一季結束時會發生什麼事？",o:["Harriet's company will move to Montana.","Harriet's company will offer Frank's company a discount.","Harriet's company will stop working with Frank's company.","Harriet's company will stop purchasing dental floss from Frank's company."],oz:["Harriet 的公司會搬到蒙大拿。","Harriet 的公司會給 Frank 折扣。","Harriet 的公司會停止和 Frank 合作。","Harriet 的公司會停止向 Frank 購買牙線。"],a:3,ex:"the latter product ＝ 列舉的最後一項 dental floss（牙線），只停買牙線，不是全面停止合作。"}
]},
{ part: 7, title: "Part 7｜A Woman on the Edge 影評",
passage: `<p><b>A Woman on the Edge</b><br>Running time: 85 minutes</p><p>Sometimes a movie is so dreadful that it almost becomes a cult classic in its own right. <i>A Woman on the Edge</i> is one such film. The storyline and acting are so dire that it brings a smile to one's face.</p><p>The film depicts a young woman named Heather who descends into madness after she discovers that her husband has been having an affair with his secretary. For years, he has claimed that he has to work late at the office, but finally Heather discovers the truth. However, when she confronts him about it, he claims she is just imagining things. Pretty soon, she loses her mind, and her evil hubby has her committed to a psychiatric hospital to get rid of her.</p><p>Starring Victoria Rule in the lead role, this appalling film is supposedly based on a true story. Viewers may find this claim hard to believe as the plot is mind-bogglingly ridiculous.</p><p>As for Ms. Rule—how the mighty have fallen. Less than five years ago, she was scooping numerous prizes for best actress at various awards ceremonies for her excellent portrayal of U.S. President Lincoln's wife, Mary. Interestingly, that film also involved playing a character who ends up in an asylum. It's sad to see her stoop to this—making straight-to-TV movies that are frankly embarrassing.</p>`,
pz: `<p><b>《邊緣女人》</b><br>片長：85 分鐘</p><p>有時候一部電影糟糕到幾乎自成一部邪典經典。《邊緣女人》就是這樣的電影。劇情和演技爛到讓人忍不住笑出來。</p><p>這部片描述一位名叫 Heather 的年輕女子，在發現丈夫和秘書外遇後陷入瘋狂。多年來，丈夫一直聲稱他得在辦公室加班，但 Heather 終於發現真相。然而，當她當面質問時，他卻說她只是胡思亂想。很快地，她精神崩潰，而她邪惡的老公把她送進精神病院以擺脫她。</p><p>由 Victoria Rule 主演的這部爛片據說改編自真實故事。觀眾可能很難相信這個說法，因為劇情荒謬到令人難以置信。</p><p>至於 Rule 小姐——真是今非昔比。不到五年前，她還因精湛詮釋美國總統林肯的妻子瑪麗，在各大頒獎典禮上囊括多座最佳女主角獎。有趣的是，那部電影也是飾演一個最後進了精神病院的角色。看到她淪落到拍這種老實說很丟臉的電視電影，真令人難過。</p>`,
qs: [
{n:68,q:"What does the reviewer imply about this movie?",qz:"影評人暗示這部電影如何？",o:["It is very well acted.","It won several awards.","It should not be on television.","It is so bad that it is enjoyable."],oz:["演技非常好。","得了好幾個獎。","不應該在電視上播。","爛到很好看。"],a:3,ex:"「so dreadful that it almost becomes a cult classic」「so dire that it brings a smile to one's face」→ 爛到讓人覺得好笑、有娛樂性。"},
{n:69,q:"What happens to the main character in the movie?",qz:"電影主角發生了什麼事？",o:["She suffers from mental health issues.","She goes to a hospital after being injured.","She discovers that her husband has no job.","She has a relationship outside of her marriage."],oz:["她有心理健康問題。","她受傷後住院。","她發現丈夫沒工作。","她有婚外情。"],a:0,ex:"她 descends into madness、loses her mind，被送進精神病院 → 心理健康問題。外遇的是丈夫。"},
{n:70,q:"What best describes the reviewer's opinion of the plot of this movie?",qz:"影評人對這部電影劇情的看法最接近哪一個？",o:["Complex","Saddening","Unbelievable","Disrespectful"],oz:["複雜的","令人難過的","令人難以置信的","不尊重的"],a:2,ex:"「Viewers may find this claim hard to believe as the plot is mind-bogglingly ridiculous」→ 不可信、荒謬。"},
{n:71,q:"Why does the reviewer think Victoria Rule's situation is sad?",qz:"影評人為什麼覺得 Victoria Rule 的處境令人難過？",o:["She has never been successful.","She used to be a respected actress.","She was once the wife of a president.","She continues to play similar characters."],oz:["她從沒成功過。","她曾經是備受尊敬的女演員。","她曾是總統夫人。","她一直演類似的角色。"],a:1,ex:"「how the mighty have fallen」她五年前還囊括多座影后 → 曾經備受尊敬，如今淪落拍爛片。她是「飾演」總統夫人。"}
]},
{ part: 7, title: "Part 7｜De Beers 鑽石",
passage: `<p>Contrary to popular belief, diamonds are not actually that rare, at least when compared to other precious stones. —[1]— The heightened prestige of diamonds can be attributed to a super effective marketing campaign by De Beers. Founded in 1888, the company took its name from two Dutch brothers who discovered diamonds on their South African farmland. —[2]— The value of diamonds skyrocketed in 1947 when Frances Gerety coined the slogan "A Diamond is Forever" and launched a series of advertisements which made diamonds a symbol of matrimony. Once the notion that diamonds were the most suitable stone to propose marriage with was engrained in the public consciousness, De Beers began advertising diamonds as a symbol of a woman's prestige and independence with their "right hand ring" campaign. —[3]— Later, De Beers established a practical monopoly on diamonds and began stockpiling them, releasing only a controlled amount into the market to further drive up their price and thereby reinforcing the stone's image as a rare commodity. —[4]—</p>`,
pz: `<p>和一般人想的相反，鑽石其實沒那麼稀有，至少和其他寶石相比是如此。—[1]— 鑽石崇高的地位，可歸功於 De Beers 極為成功的行銷活動。該公司成立於 1888 年，名稱取自兩位在南非農地上發現鑽石的荷蘭兄弟。—[2]— 不過，De Beers 實際上是由礦業大亨、狂熱的帝國主義者塞西爾・羅德斯擁有並經營。1947 年，Frances Gerety 創造了「鑽石恆久遠」這句標語，並推出一系列讓鑽石成為婚姻象徵的廣告，鑽石的價值隨之飆升。當「鑽石是最適合求婚的寶石」這個觀念深植人心後，De Beers 又以「右手戒」廣告，把鑽石宣傳成女性地位與獨立的象徵。—[3]— 後來，De Beers 實質壟斷了鑽石市場並開始囤積鑽石，只釋出受控制的數量到市場上，進一步推高價格，從而強化鑽石作為稀有商品的形象。—[4]—</p>`,
qs: [
{n:72,q:"When was De Beers founded?",qz:"De Beers 是什麼時候成立的？",o:["1988","1888","1847","1947"],oz:["1988","1888","1847","1947"],a:1,ex:"「Founded in 1888」。1947 是標語誕生的年份，陷阱！"},
{n:73,q:"According to the passage, what did De Beers most strongly associate diamonds with?",qz:"根據文章，De Beers 最強烈地把鑽石和什麼連結在一起？",o:["Youth and freedom","Age and experience","Love and matrimony","Ruthlessness and power"],oz:["青春與自由","年齡與經驗","愛情與婚姻","冷酷與權力"],a:2,ex:"「made diamonds a symbol of matrimony」「the most suitable stone to propose marriage with」→ 愛情與婚姻。"},
{n:74,q:"How did De Beers manipulate the diamond market?",qz:"De Beers 如何操縱鑽石市場？",o:["By destroying diamonds","By stockpiling diamonds","By selling diamonds only to celebrities","By saturating the market with diamonds"],oz:["銷毀鑽石","囤積鑽石","只賣給名人","讓市場充斥鑽石"],a:1,ex:"「began stockpiling them, releasing only a controlled amount into the market」→ 囤積。"},
{n:75,q:"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"However, De Beers was actually owned and managed by mining magnate and ardent imperialist Cecil Rhodes.\"",qz:"下列句子最適合放在哪個位置？\n「不過，De Beers 實際上是由礦業大亨、狂熱帝國主義者塞西爾・羅德斯擁有並經營。」",o:["[1]","[2]","[3]","[4]"],oz:["[1]","[2]","[3]","[4]"],a:1,ex:"[2] 前一句說公司名稱取自荷蘭兄弟，However 轉折說明「但實際擁有者是羅德斯」最合理。"}
]},
{ part: 7, title: "Part 7｜租屋詐騙",
passage: `<p>Dear Ms. Lin,</p><p>Thank you for messaging me on FB! I am very glad that you have taken an interest in my apartment posting. I purchased the apartment for my American son when he was attending NTNU, but now he is gone to America, so I just want to rent the apartment out. As you can see from the pictures I placed on that apartment posting Web site, 692.com, it is a luxury apartment, and it is very real. It has five massive rooms, a massive kitchen, a massive living room, a massive balcony, and two massive bathrooms. Don't worry; all the utilities are free. And yes, the rent is only NT$20,000 a month. I'm an American and don't know anyone to rent the apartment to, so it doesn't matter to me that it's so cheap, because right now nobody's using it.</p><p>Because I live in America, I can't come to the apartment and let you see it. So here's what we can do. First you can pay the damage deposit (one month's rent) into the account listed below.</p><p>Account number: 7474 5757 8888 5555</p><p>And once I get it, I'll mail you the key to the apartment, and you can inspect it. If you don't like the apartment, you can just tell me, and I will definitely transfer the damage deposit back to you. I promise.</p><p>With everlasting love,</p><p>Sue Doenim</p><hr><p>Dear Whatever Your Real Name Is,</p><p>I thought it best to contact you to see if this were a real opportunity, but unfortunately my suspicions have been confirmed. I was immediately wary of the pictures you posted. For one, the apartment you listed seemed too good to be true. It seemed bizarre that you listed what was obviously a much more expensive apartment at a fourth of the price. Thus, I started looking through your Facebook profile to see if something was off. It was strange that you only had five photos of you and your family, and that your Facebook history only goes back two weeks. Additionally, your proposition that I give you money up front and then expect a key in the mail seemed completely bogus. Why would I ever give a stranger that much money in good faith? What really cinched it for me, though, was when my husband pointed out how your Facebook messenger showed that your message was sent from Taipei. The apartment was never real, was it? I have informed the authorities about your posting and your account. They will be looking into it further.</p><p>Michelle Lin</p>`,
pz: `<p>親愛的林小姐：</p><p>謝謝你在臉書上傳訊息給我！很高興你對我的公寓刊登有興趣。我是在我的美國兒子就讀師大時幫他買了這間公寓，但現在他回美國了，所以我只想把公寓租出去。你可以從我放在租屋網站 692.com 上的照片看到，這是一間豪華公寓，而且千真萬確。它有五間超大房間、超大廚房、超大客廳、超大陽台和兩間超大浴室。別擔心，所有水電費全免。沒錯，租金每月只要新台幣 2 萬元。我是美國人，不認識可以租給的人，所以這麼便宜對我來說無所謂，因為現在根本沒人在用。</p><p>因為我住在美國，沒辦法過去讓你看房。所以我們可以這樣做：你先把押金（一個月租金）匯到下面的帳戶。</p><p>帳號：7474 5757 8888 5555</p><p>我收到後，就把公寓鑰匙寄給你，你就可以去看房。如果你不喜歡，只要告訴我，我一定會把押金退還給你。我保證。</p><p>永遠愛你的<br>Sue Doenim</p><hr><p>不管你真名叫什麼：</p><p>我原本覺得最好先聯絡你，看看這是不是真的機會，但很遺憾，我的懷疑被證實了。我一看到你貼的照片就起了戒心。首先，你刊登的公寓好得令人難以置信。你把一間明顯貴得多的公寓用四分之一的價格刊登，實在很詭異。所以我開始翻你的臉書個人檔案，看看有沒有什麼不對勁。奇怪的是你只有五張你和家人的照片，而且你的臉書紀錄只有兩週。此外，你要我先付錢再等鑰匙寄來的提議，完全是騙局。我為什麼要誠心誠意地把那麼多錢給一個陌生人？不過真正讓我確定的，是我先生指出你的臉書 Messenger 顯示訊息是從台北發出的。這間公寓根本不存在，對吧？我已經向有關當局檢舉了你的刊登和帳號，他們會進一步調查。</p><p>Michelle Lin</p>`,
qs: [
{n:76,q:"What does Michelle believe the listed apartment's actual price would be?",qz:"Michelle 認為這間公寓的實際價格應該是多少？",o:["NT$20,000","NT$40,000","NT$60,000","NT$80,000"],oz:["2 萬元","4 萬元","6 萬元","8 萬元"],a:3,ex:"「at a fourth of the price」→ 2 萬是實際價格的四分之一 → 20,000 × 4 ＝ 80,000。"},
{n:77,q:"What was the first detail cited as suspicious by Michelle Lin?",qz:"Michelle Lin 最先提到的可疑之處是什麼？",o:["Sue's lack of profile pictures","Sue's short Facebook history","Sue's posting of the apartment at a low price","Sue's continued repetition that she is American"],oz:["Sue 的大頭照很少","Sue 的臉書紀錄很短","Sue 以低價刊登公寓","Sue 一直強調自己是美國人"],a:2,ex:"「For one, the apartment you listed seemed too good to be true… at a fourth of the price」→ 第一個疑點是低價。"},
{n:78,q:"What seems to be Sue Doenim's scheme?",qz:"Sue Doenim 的詐騙手法似乎是什麼？",o:["Getting people to pay her rent for her","Overcharging people to stay in a bad apartment","Luring people into her apartment and robbing them","Tricking people into sending her money for nothing"],oz:["讓別人幫她付房租","向人收高價住爛公寓","把人騙到公寓再搶劫","騙人匯錢卻什麼都不給"],a:3,ex:"要對方先匯押金，公寓「never real」→ 騙錢卻沒有任何東西。"},
{n:79,q:"Where did Michelle Lin first learn about Sue Doenim's apartment posting?",qz:"Michelle Lin 最初是在哪裡看到 Sue Doenim 的租屋刊登？",o:["From a flyer","On Facebook","From her husband","On an apartment rental Web site"],oz:["傳單","臉書","她先生","租屋網站"],a:3,ex:"「the pictures I placed on that apartment posting Web site, 692.com」→ 租屋網站。臉書是她們聯絡的管道。"},
{n:80,q:"Who did Michelle contact before responding to Sue Doenim?",qz:"Michelle 在回覆 Sue Doenim 之前聯絡了誰？",o:["A lawyer","Her bank","The police","Her current landlord"],oz:["律師","她的銀行","警察","她現在的房東"],a:2,ex:"「I have informed the authorities」→ 有關當局 ＝ 警察。"}
]},
{ part: 7, title: "Part 7｜拾獲金婚戒",
passage: `<p>Posted: May 3, 2017<br>Found: One gold wedding ring</p><p>My wife and I were walking along the bank of Redfish Lake when we spotted something shiny in the water. I reached in and pulled out what seems to be a solid gold wedding ring. Based on the style and size, I'm guessing that this ring belonged to a larger man, but this is just a guess. If this is your wedding ring, please contact me by e-mail at chrisrodan@hotmail.com or by phone at 1-555-777-621. If you choose to contact me by phone, please call between 7:00 p.m. and 9:30 p.m. or on weekends.</p><p>Best,<br>Chris Rodan</p><hr><p>To: chrisrodan@hotmail.com<br>Subject: I found the owner of that lost wedding ring!</p><p>Hey Chris!</p><p>Chris old boy—it's a small world! You won't believe it. I saw your post, thought, "Too bad for the poor fellow who lost it," and went about my business. A week later, in walks this couple, and they're both GIGANTIC! Seriously, the biggest people I've ever seen—both over seven feet tall. No joking! Anyway, they come into my jewelry shop, and they say they want to buy a gold wedding ring. I congratulate them on getting engaged, and they say they've been married for years. The husband (his name is Glen) became embarrassed and told me that he'd lost his original wedding ring while practicing capoeira (some kind of martial art that resembles dance-fighting) near Redfish Lake. At this point, I got really excited, pulled out my smartphone, went to your post, and said, "This wedding ring?" and they both said, "YEAH!" and I said, "Hey, my brother found it! I'll get him to drop it off here, and you guys can come get it!" Anyway, pop by my store whenever it's convenient and drop off the ring.</p><p>Be seeing you,<br>Martin</p>`,
pz: `<p>刊登日期：2017 年 5 月 3 日<br>拾獲：一枚金色婚戒</p><p>我和太太沿著 Redfish 湖畔散步時，看到水裡有東西在發亮。我伸手撈出來，看起來是一枚純金婚戒。從款式和尺寸來看，我猜這枚戒指的主人是個體型較大的男性，但這只是猜測。如果這是你的婚戒，請寄信到 chrisrodan@hotmail.com 或撥打 1-555-777-621 聯絡我。如果選擇打電話，請在晚上 7:00 到 9:30 之間或週末來電。</p><p>Chris Rodan</p><hr><p>收件者：chrisrodan@hotmail.com<br>主旨：我找到那枚婚戒的主人了！</p><p>嘿 Chris！</p><p>老兄——世界真小！你絕對不會相信。我看到你的貼文，心想「弄丟戒指的可憐傢伙真倒楣」，然後就去忙自己的事了。一週後，走進來一對夫妻，兩個人都超級巨大！說真的，是我見過最高大的人——兩個都超過七呎（約 213 公分）。不是開玩笑！總之，他們走進我的珠寶店，說想買一枚金婚戒。我恭喜他們訂婚，他們卻說已經結婚好幾年了。丈夫（他叫 Glen）很不好意思地告訴我，他在 Redfish 湖附近練卡波耶拉（一種類似舞蹈格鬥的武術）時弄丟了原本的婚戒。這時我超興奮，拿出手機點開你的貼文問：「是這枚婚戒嗎？」他們倆異口同聲說：「對！」我就說：「嘿，是我弟／哥撿到的！我叫他拿來店裡，你們再來拿！」總之，你方便的時候順道來我店裡把戒指放著吧。</p><p>回頭見，<br>Martin</p>`,
qs: [
{n:81,q:"When can it be assumed that Martin met the couple?",qz:"可以推斷 Martin 是在哪一天遇到那對夫妻？",o:["May 3","May 4","May 10","May 23"],oz:["5 月 3 日","5 月 4 日","5 月 10 日","5 月 23 日"],a:2,ex:"貼文 5 月 3 日，他看到貼文後「A week later」夫妻才來店裡 → 約 5 月 10 日。"},
{n:82,q:"Why did Glen lose his wedding ring?",qz:"Glen 為什麼弄丟了婚戒？",o:["He dropped it while playing with it.","He lost it while reeling in a big fish.","He threw it into the lake while angry.","He lost it while practicing a martial art."],oz:["玩戒指時掉了。","釣大魚時弄丟了。","生氣時丟進湖裡。","練武術時弄丟了。"],a:3,ex:"「he'd lost his original wedding ring while practicing capoeira (some kind of martial art…)」。"},
{n:83,q:"How does Martin know Chris?",qz:"Martin 和 Chris 是什麼關係？",o:["They're friends.","They're brothers.","They're neighbors.","They're business partners."],oz:["朋友","兄弟","鄰居","生意夥伴"],a:1,ex:"Martin 對夫妻說「Hey, my brother found it!」→ 兄弟。"},
{n:84,q:"Which of the following best describes the tone of Martin's e-mail?",qz:"下列哪一項最能形容 Martin 郵件的語氣？",o:["Personal and playful","Brief and professional","Academic and verbose","Respectful and somber"],oz:["親切而輕鬆有趣","簡短而專業","學術而冗長","恭敬而嚴肅"],a:0,ex:"Chris old boy、GIGANTIC!、No joking! → 口語、親暱、俏皮。"},
{n:85,q:"What information in Chris's post was confirmed by Martin?",qz:"Chris 貼文中的哪個資訊被 Martin 證實了？",o:["The way the ring was lost","The material of the ring","The location of the ring","The size of the owner of the ring"],oz:["戒指遺失的方式","戒指的材質","戒指的位置","戒指主人的體型"],a:3,ex:"Chris 猜主人是「a larger man, but this is just a guess」，Martin 證實夫妻都超過七呎高 → 證實了主人體型。"}
]},
{ part: 7, title: "Part 7｜Shipley 庭園造景估價",
passage: `<p style="text-align:center"><b><i>Shipley Landscaping Services</i></b></p><p>Have you been dreaming about giving your yard a makeover, but you aren't ready to pull the trigger yet? We here at Shipley Landscaping understand that investing in your yard is a big decision. So, why don't you stop by our demo home on 4th Street and Vine to see what we can do for you? The entire property is beautifully landscaped and labeled with prices. We'll give you an estimate so you can get an idea of how much your project will cost and what it will look like when it's done.</p><p>Shipley Landscaping Services is the premier name in landscaping in the tri-state area. We've been featured on Channel 8 news and have received a five-star rating from betterlocalbusiness.com. Mention this ad and save 15 percent on your project's bill!</p><table><tr><th colspan="4">SHIPLEY LANDSCAPING ESTIMATE #1574</th></tr><tr><th>DESCRIPTION</th><th>#</th><th>AMOUNT</th><th>TOTAL</th></tr><tr><td>01. Sidewalk repave linear foot (Classic Cobble #R21)</td><td>47</td><td>$17.81</td><td>$837.07</td></tr><tr><td>02. Lawn resod square foot (Bermuda #B17)</td><td>2007</td><td>$0.49</td><td>$983.43</td></tr><tr><td>03. Flower bed 3x1 linear foot (Begonia #FB037)</td><td>16</td><td>$11.50</td><td>$184.00</td></tr><tr><td>04. White picket fence linear foot (#F001)</td><td>49</td><td>$27.75</td><td>$1,359.75</td></tr><tr><td>05. Retaining wall linear foot (cinder block #CB001) Height modifier 1 foot (x5)</td><td>125</td><td>$15.05 x 5</td><td>$9,406.25</td></tr><tr><td>06. Labor per day (8 hours) Manpower modifier (x3)</td><td>8</td><td>$400 x 3</td><td>$9,600</td></tr><tr><td>Discount</td><td></td><td>15%</td><td>-$3,355.58</td></tr><tr><td></td><td></td><td><b>TOTAL</b></td><td><b>$19,014.92</b></td></tr></table><hr><p>To: mark@shipleylandscaping.com<br>From: janice@email.com<br>Subject: Landscaping estimate</p><p>Shipley Landscaping Services,</p><p>I recently had the opportunity to stop by your demo home to check out the possibilities for an upcoming yard makeover my family was planning. I was helped by Tom, and he was able to give us an estimate for our project. I was shocked by how few people your company will need for the job; that is impressive. However, the estimate you provided exceeds our budget of $15,000. I have had estimates from other landscaping companies, and your company is a bit on the expensive side. My husband suggested skipping one of our intended renovations to reduce the price, but the only project I'm willing to cut is, unfortunately, the cheapest one! Is there any way to negotiate a lower price?</p><p>Regards,<br>Janice</p>`,
pz: `<p style="text-align:center"><b>Shipley 庭園造景服務</b></p><p>你是否一直夢想改造自家庭院，卻還沒準備好下決定？我們 Shipley 造景了解投資庭院是個重大決定。何不到我們位於第四街與 Vine 街口的示範屋，看看我們能為你做些什麼？整個房產都經過精美造景，並標示了價格。我們會提供估價，讓你了解專案的費用以及完成後的樣子。</p><p>Shipley 造景服務是三州地區首屈一指的造景品牌。我們曾登上第 8 頻道新聞，並獲得 betterlocalbusiness.com 五星評價。提及本廣告，專案帳單可省 15%！</p><p><b>Shipley 造景估價單 #1574</b><br>01. 人行道重鋪（每線性呎）47 × $17.81 ＝ $837.07<br>02. 草皮重鋪（每平方呎）2007 × $0.49 ＝ $983.43<br>03. 花圃 3×1（每線性呎）16 × $11.50 ＝ $184.00<br>04. 白色尖樁籬笆（每線性呎）49 × $27.75 ＝ $1,359.75<br>05. 擋土牆（每線性呎，高度係數 ×5）125 × $15.05 × 5 ＝ $9,406.25<br>06. 每日工資（8 小時，人力係數 ×3）8 × $400 × 3 ＝ $9,600<br>折扣 15%：-$3,355.58<br><b>總計：$19,014.92</b></p><hr><p>收件者：mark@shipleylandscaping.com<br>寄件者：janice@email.com<br>主旨：造景估價</p><p>Shipley 造景服務：</p><p>我最近有機會到你們的示範屋，看看我家計畫中的庭院改造有哪些可能。Tom 接待了我，並幫我們估了價。我很驚訝你們公司這份工作只需要這麼少人，真是令人佩服。不過，你們提供的估價超出了我們 15,000 美元的預算。我也找過其他造景公司估價，你們公司稍微偏貴。我先生建議放棄其中一項預定的改造來降低價格，但很不巧，我唯一願意砍掉的項目是最便宜的那一項！有沒有辦法談個更低的價格？</p><p>Janice 敬上</p>`,
qs: [
{n:86,q:"In the advertisement, the word \"demo\" in paragraph 1 is closest in meaning to",qz:"廣告第 1 段中的「demo」意思最接近",o:["best","first","example","only"],oz:["最好的","第一的","範例、示範","唯一的"],a:2,ex:"demo home ＝ 示範屋 → example（範例）。"},
{n:87,q:"What are Shipley Landscaping customers advised to do?",qz:"廣告建議 Shipley 的顧客做什麼？",o:["Shop around first","Write an estimate","Go to betterlocalbusiness.com","Check out their work first"],oz:["先貨比三家","寫一份估價","上 betterlocalbusiness.com","先參觀他們的作品"],a:3,ex:"「why don't you stop by our demo home… to see what we can do for you?」→ 先去看他們的作品。"},
{n:88,q:"What do we know from estimate #1574?",qz:"從估價單 #1574 我們知道什麼？",o:["It is not complete.","It took hours to write.","It is the first time Janice has gotten an estimate.","Janice mentioned the ad."],oz:["它還沒完成。","寫了好幾個小時。","這是 Janice 第一次拿到估價。","Janice 有提到廣告。"],a:3,ex:"估價單有 15% 折扣，而廣告說「Mention this ad and save 15 percent」→ 她有提到廣告。她也找過其他公司估價，(C) 錯。"},
{n:89,q:"What renovation was Janice willing to do without?",qz:"Janice 願意放棄哪一項改造？",o:["The sidewalk repave","The lawn resod","The flower bed","The white picket fence"],oz:["人行道重鋪","草皮重鋪","花圃","白色尖樁籬笆"],a:2,ex:"她只願意砍「最便宜的那一項」→ 花圃 $184.00 最便宜。"},
{n:90,q:"What really surprised Janice about the estimate?",qz:"估價單中真正讓 Janice 驚訝的是什麼？",o:["How expensive the retaining wall will be","How cheap the fence will be","How long it took to get the estimate","How few people will be needed"],oz:["擋土牆有多貴","籬笆有多便宜","拿到估價花了多久","需要的人有多少"],a:3,ex:"「I was shocked by how few people your company will need for the job」→ 需要的人很少（人力係數只有 ×3）。"}
]},
{ part: 7, title: "Part 7｜Fighting Spirit 耳機訂單",
passage: `<p><b>Fighting Spirit Audio Order Form</b></p><table><tr><td><b>Order No:</b> #110325611<br><b>Product:</b><br>Shadow Boxer Pro-11<br>• Wireless, sweat-proof earphones<br><b>Units:</b> Two</td><td><b>Delivery Address:</b><br>1609 Seaside Dr,<br>Galveston, TX, 77550</td></tr><tr><td><b>Date Dispatched:</b><br>July 19, 2017</td><td><b>Payment Method:</b><br>American Express<br>************2208 / Exp. 07/11/2023</td></tr><tr><td><b>Notes:</b> Unavailable in specified color (blue), so gray model dispatched instead. Free mini power bank included to make up for the inconvenience of this shortcoming.</td><td><b>Amount:</b><br>Shadow Boxer Pro-11<br>$159.00 x 2 = $318.00<br><b>Subtotal:</b> $318.00<br><b>Delivery:</b> $15.49<br><b>Total:</b> $353.49</td></tr></table><p>Fighting Spirit products are built specifically with martial arts practitioners in mind.<br>Contact Customer Support if there are any mistakes with your order.<br>Contact Help if you need to update your payment methods or address.</p><hr><p>To: help@products.fightingspirit.com<br>From: wilmamcgillis@betternet.com</p><p>Dear Sir or Madam:</p><p>Re: Order No: #110325611</p><p>I am writing in connection with the above order, which I have copied into the body of this e-mail.</p><p>I have never experienced so many problems with an online purchase before. Let's begin with the total amount you charged me. A quick glance at the amount section of the order form reveals that something's wrong! Do you not check these things before they are sent?</p><p>Second, imagine my surprise when I opened the box and the special ear locks—one of the main reasons I buy this product—were nowhere to be seen! Third, the product is advertised as having a 10-hour battery life, but it's actually around half of that!</p><p>I expect to be refunded the extra amount I was charged, sent new ear locks—with fast shipping—and I am also hoping for another gesture of goodwill on your part. Perhaps another item from your catalog? I look forward to your reply.</p><p>Regards,<br>Wilma M. McGillis</p><hr><p>To: wilmamcgillis@betternet.com<br>From: keith@customersupport.fightingspirit.com</p><p>Dear Ms. McGillis:</p><p>We at Fighting Spirit deeply apologize for the problems with your order. As compensation, we will refund the extra amount you were charged as well as provide you with a digital coupon that can be used towards your next Fighting Spirit online purchase. Enter the following code on our Web site [VSPL54406] to receive 50 percent off your next order! We will also send you an ear lock for each pair of earphones—via express shipping—free of charge.</p><p>Sincerely,<br>Keith Morris<br>Customer Support Representative<br>Fighting Spirit</p>`,
pz: `<p><b>Fighting Spirit 音響訂購單</b></p><p>訂單編號：#110325611<br>產品：Shadow Boxer Pro-11（無線防汗耳機）×2<br>寄送地址：德州 Galveston，Seaside 路 1609 號<br>出貨日期：2017 年 7 月 19 日<br>付款方式：美國運通卡末四碼 2208／到期 2023/07/11<br>備註：指定顏色（藍色）缺貨，改寄灰色款。附贈迷你行動電源，彌補此不便。<br>金額：$159.00 × 2 ＝ $318.00；小計 $318.00；運費 $15.49；總計 $353.49</p><p>Fighting Spirit 產品專為武術練習者設計。<br>訂單若有任何錯誤，請聯絡客服部（Customer Support）。<br>若需更新付款方式或地址，請聯絡協助部（Help）。</p><hr><p>收件者：help@products.fightingspirit.com<br>寄件者：wilmamcgillis@betternet.com</p><p>敬啟者：</p><p>關於：訂單編號 #110325611</p><p>我寫信是關於上述訂單，我已將訂單內容複製到這封郵件內文中。</p><p>我從沒在網路購物時遇過這麼多問題。先從你們向我收的總金額說起。只要快速看一下訂購單的金額欄位，就會發現有問題！你們寄出前都不檢查的嗎？</p><p>第二，想像一下我打開盒子時有多驚訝，特製耳掛——我買這個產品的主要原因之一——竟然不見蹤影！第三，產品廣告說電池續航 10 小時，但實際上只有大約一半！</p><p>我要求退還多收的金額、寄給我新的耳掛（要快速寄送），我也希望你們能再表示一點誠意。也許從你們的目錄再送我一樣商品？期待你們的回覆。</p><p>Wilma M. McGillis 敬上</p><hr><p>收件者：wilmamcgillis@betternet.com<br>寄件者：keith@customersupport.fightingspirit.com</p><p>McGillis 女士您好：</p><p>Fighting Spirit 對您訂單所發生的問題深感抱歉。作為補償，我們將退還多收的金額，並提供您一張可用於下次 Fighting Spirit 線上購物的電子折價券。在我們的網站輸入代碼 [VSPL54406]，下次訂單即可享五折優惠！我們也會以快遞免費為每副耳機寄送一個耳掛。</p><p>Fighting Spirit 客服代表<br>Keith Morris 敬上</p>`,
qs: [
{n:91,q:"Who might this product be aimed at?",qz:"這個產品的目標客群可能是誰？",o:["An artist with a heavy workload","A traveler who has a lot of luggage","A person who engages in fighting sports","A jewelry designer facing challenging conditions"],oz:["工作量大的藝術家","行李很多的旅客","從事格鬥運動的人","面對艱難環境的珠寶設計師"],a:2,ex:"「built specifically with martial arts practitioners in mind」→ 武術／格鬥運動者。"},
{n:92,q:"Why is an extra item included in the order?",qz:"為什麼訂單中多附了一項商品？",o:["The customer requested it.","The company put the item in by mistake.","The company had a special promotion happening.","The company didn't have exactly what the customer wanted."],oz:["客戶要求的。","公司不小心放進去的。","公司正在辦促銷。","公司沒有客戶想要的確切商品。"],a:3,ex:"藍色缺貨改寄灰色，附贈行動電源「to make up for the inconvenience」→ 因為沒有客戶要的顏色。"},
{n:93,q:"What do we know about Wilma?",qz:"關於 Wilma 我們知道什麼？",o:["Her e-mail was accompanied by an attachment.","She contacted the wrong department.","She e-mailed Keith directly.","Her message was ignored by Fighting Spirit."],oz:["她的郵件附了附件。","她聯絡錯部門了。","她直接寄信給 Keith。","她的訊息被 Fighting Spirit 忽略了。"],a:1,ex:"訂單錯誤應聯絡 Customer Support，她卻寄給 help@（Help 是處理付款方式與地址的）→ 聯絡錯部門。她說訂單「copied into the body」不是附件。"},
{n:94,q:"What is Wilma's first complaint?",qz:"Wilma 的第一個抱怨是什麼？",o:["She did not get the color she asked for.","She did not receive the product on time.","She was not charged the correct amount.","She did not receive an item that she wanted."],oz:["她沒拿到指定的顏色。","她沒準時收到產品。","她被收取的金額不正確。","她沒收到想要的東西。"],a:2,ex:"「Let's begin with the total amount you charged me… something's wrong!」→ 金額錯誤（$318 + $15.49 應為 $333.49，卻收 $353.49）。"},
{n:95,q:"Which of Wilma's demands was NOT met by Keith?",qz:"Wilma 的哪項要求 Keith「沒有」滿足？",o:["A refund","New ear locks","A new product","Expedited shipping"],oz:["退款","新耳掛","新產品（另一件商品）","快速寄送"],a:2,ex:"Keith 退款、免費快遞耳掛，但沒有送另一件商品，只給了五折折價券。"}
]},
{ part: 7, title: "Part 7｜產品線銷售數字",
passage: `<p>From: Wilson Mathis (wmath@worldsales.com)<br>To: Eric Johnson (johnson@worldsales.com)<br>Subject: Product numbers<br>Sent: Feb 8, 13:06</p><p>Dear Mr. Johnson,</p><p>Here are the statistics I was speaking about in the meeting. I know a few people you've met with were interested in seeing some of our financials, but we also discussed the possibility of discontinuing a few of the less impressive models. As I mentioned previously, some of these numbers (units sold listed in millions) might not look superb—especially the numbers from our worst year. We could cut a few product lines to eliminate some overhead and simplify our business so we can focus on the items that sell well. I think the candidates are obvious, and I'd be excited about streamlining. Please let me know if you have any questions.</p><p>Thanks,<br>Wilson M.</p><hr><p>Major product lines over a four-year period:<br>Many of the products remained relatively stable and recovered in the event of an economic slump. Lower-volume or new lines are not included.<br>Units listed in millions</p><table><tr><th>NAME</th><th>2014</th><th>2015</th><th>2016</th><th>2017</th></tr><tr><td>Model 4200B</td><td>4.18</td><td>3.6</td><td>4.02</td><td>4.09</td></tr><tr><td>Model 860C</td><td>3.4</td><td>3.1</td><td>3.2</td><td>3.41</td></tr><tr><td>Model 115F</td><td>0.87</td><td>0.83</td><td>0.94</td><td>1.37</td></tr><tr><td>Model AR110</td><td>1.8</td><td>1.4</td><td>1.6</td><td>2.5</td></tr><tr><td>Model B16</td><td>2.1</td><td>0.96</td><td>1.1</td><td>1.7</td></tr><tr><td>Model 2210M</td><td>1.06</td><td>0.99</td><td>1.04</td><td>1.05</td></tr></table><hr><p>From: Eric Johnson (johnson@worldsales.com)<br>To: Wilson Mathis (wmath@worldsales.com)<br>Subject: RE: Product numbers<br>Sent: Feb 9, 15:32</p><p>Will,</p><p>Thanks for these. I know this is just a selection of our total product offering over the past four years, and I don't want to overwhelm any potentially interested parties with pages and pages of financials. But anyone considering an acquisition of our company is going to want to see how well the most popular products are performing. However, I want to point out that if we're cutting any product at all, it shouldn't be the one with the lowest volume—it should be the one with the least growth potential. A few of the lower-volume items have shown substantial growth, and we should certainly keep them on the table in hopes that that trend continues. Ever since I started this company, it's always been these types of products that performed best. In fact, I think the recovery from a rough patch works in our favor. That's a good sign. Keep in mind that I'll need to make a decision quickly. I need to get back with the interested parties ASAP. The acquisition process will still take a long time once it gets rolling.</p><p>Thanks,<br>EJ</p>`,
pz: `<p>寄件者：Wilson Mathis<br>收件者：Eric Johnson<br>主旨：產品數據<br>寄件時間：2 月 8 日 13:06</p><p>Johnson 先生您好：</p><p>這是我在會議中提到的統計數據。我知道您見過的幾位人士有興趣看看我們的一些財務資料，不過我們也討論了停產幾款表現較差型號的可能性。如我先前所說，其中一些數字（銷售量以百萬台計）可能不太亮眼——尤其是我們最差那一年的數字。我們可以砍掉幾條產品線來削減一些營運成本、精簡業務，專注於賣得好的商品。我認為該砍的對象很明顯，我很樂見精簡化。如有任何問題請告訴我。</p><p>謝謝，<br>Wilson M.</p><hr><p><b>四年間的主要產品線</b>（單位：百萬台）<br>許多產品相對穩定，並在經濟衰退時回升。不含銷量較低或新的產品線。</p><p>4200B：4.18／3.6／4.02／4.09<br>860C：3.4／3.1／3.2／3.41<br>115F：0.87／0.83／0.94／1.37<br>AR110：1.8／1.4／1.6／2.5<br>B16：2.1／0.96／1.1／1.7<br>2210M：1.06／0.99／1.04／1.05<br>（依序為 2014／2015／2016／2017 年）</p><hr><p>寄件者：Eric Johnson<br>收件者：Wilson Mathis<br>主旨：回覆：產品數據<br>寄件時間：2 月 9 日 15:32</p><p>Will：</p><p>謝謝你提供這些。我知道這只是我們過去四年全部產品的一部分，我也不想用一頁又一頁的財務資料淹沒任何潛在有興趣的人。但任何考慮收購我們公司的人，都會想看看最熱門的產品表現如何。不過我要指出，如果我們真要砍掉任何產品，不應該砍銷量最低的——而應該砍成長潛力最小的。有幾項銷量較低的產品已展現顯著成長，我們當然應該保留它們，希望這個趨勢持續下去。自從我創立這家公司以來，一直都是這類產品表現最好。事實上，我認為從低谷中回升對我們有利，這是個好兆頭。請記住我需要盡快做決定。我得盡快回覆有興趣的買家。收購程序一旦啟動，還是會花很長時間。</p><p>謝謝，<br>EJ</p>`,
qs: [
{n:96,q:"What is the purpose of Wilson's e-mail?",qz:"Wilson 這封郵件的目的是什麼？",o:["To ask a question about the chart","To update Eric Johnson about the result of the meeting","To inform Eric Johnson of a decision that was made","To give his input on the statistics he's providing"],oz:["詢問圖表的問題","向 Eric 報告會議結果","通知 Eric 已做出的決定","對他提供的數據發表意見"],a:3,ex:"他提供數據，並表達「可以砍掉幾條產品線、我很樂見精簡」的看法 → 給予意見。決定尚未做出。"},
{n:97,q:"What year does Wilson reference in his e-mail?",qz:"Wilson 在郵件中提到哪一年？",o:["2014","2015","2016","2017"],oz:["2014","2015","2016","2017"],a:1,ex:"他提到「the numbers from our worst year」，表格中幾乎所有產品在 2015 年銷量最低 → 2015。"},
{n:98,q:"Which product would Eric most want to keep?",qz:"Eric 最想保留哪一項產品？",o:["Model 860C","Model AR110","Model 2210M","Model B16"],oz:["860C","AR110","2210M","B16"],a:1,ex:"Eric 重視「成長潛力」與「從低谷回升」。AR110 從 2015 年的 1.4 成長到 2017 年的 2.5，成長幅度最大。"},
{n:99,q:"What is Eric Johnson's most likely position in the company?",qz:"Eric Johnson 在公司中最可能是什麼職位？",o:["Wilson's subordinate","Sales director","CEO","Marketing director"],oz:["Wilson 的下屬","業務總監","執行長","行銷總監"],a:2,ex:"「Ever since I started this company」→ 他是公司創辦人，且要決定是否被收購 → CEO。"},
{n:100,q:"Why are the two people most likely discussing this information?",qz:"兩人最可能為什麼討論這些資訊？",o:["They are trying to determine the reason for poor sales.","They are discussing which products should be promoted.","Eric is a new manager and needs to understand the business.","Someone is interested in buying the company."],oz:["他們要找出銷售不佳的原因。","他們在討論要推廣哪些產品。","Eric 是新經理，需要了解業務。","有人有興趣收購這家公司。"],a:3,ex:"「anyone considering an acquisition of our company」「I need to get back with the interested parties」→ 有人想收購公司。"}
]}
]
});
